import {
	AfterViewInit,
	Component,
	ElementRef,
	Input,
	OnChanges, OnDestroy,
	SimpleChanges,
	ViewChild, ViewEncapsulation,
	forwardRef
} from '@angular/core';
import EasyMDE from 'easymde';
import { EspdAbstractSizeableInputDirective, espdAbstractInputComponentInjectionToken } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';

@Component({
	selector: 'espd-markdown-editor',
	templateUrl: 'markdown.component.html',
	imports: [
		InputScaffoldComponent
	],
	encapsulation: ViewEncapsulation.None,
	styleUrls: [
		'markdown.component.scss',
		'../../../../../node_modules/easymde/dist/easymde.min.css'
	],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => MarkdownEditorComponent) }]
})
export class MarkdownEditorComponent extends EspdAbstractSizeableInputDirective implements OnChanges, OnDestroy, AfterViewInit {

	@ViewChild('editor')
	public textarea!: ElementRef<HTMLTextAreaElement>;

	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	private simplemde: any;

	@Input()
	public toolbarConfiguration: ('bold' | 'italic' | '|' | 'link' | 'preview')[] = ['bold', 'italic', '|', 'link', '|', 'preview'];

	public ngOnChanges(changes: SimpleChanges): void {
		super.ngOnChanges(changes);
		if (this.simplemde) {
			this.destroyEditor();
			this.setupEditor();
		}
	}

	public ngAfterViewInit(): void {
		this.setupEditor();
	}

	public ngOnDestroy(): void {
		super.ngOnDestroy();
		this.destroyEditor();
	}

	public refresh(): void {
		if (this.simplemde) {
			this.simplemde.codemirror.refresh();
		}
	}

	private setupEditor() {
		setTimeout(() => {
			this.simplemde = new EasyMDE({
				element: this.textarea.nativeElement,
				toolbar: this.toolbarConfiguration,
				initialValue: this.control?.value ?? '',
				autofocus: false,
				spellChecker: false,
				status: false,
				autoDownloadFontAwesome: false
			});

			this.simplemde.codemirror.options.extraKeys.Tab = false;
			this.simplemde.codemirror.options.extraKeys['Shift-Tab'] = false;
			this.simplemde.codemirror.options.inputStyle = 'contenteditable';
			this.simplemde.codemirror.display.input.textarea.setAttribute('aria-labelledby', `espd-input-${this.id} espd-input-${this.id}-directions`);

			for (const element of this.simplemde.gui.toolbar.children) {
				if (element.tagName === 'BUTTON') {
					element.tabIndex = 0;
				}
			}

			this.simplemde.codemirror.on('change', () => {
				this.control.setValue(this.simplemde?.value());
				this.control.markAsDirty();
			});
		}, 300);
	}

	private destroyEditor() {
		if (this.simplemde) {
			try {
				this.simplemde.toTextArea();
			} catch {
				// https://github.com/Ionaru/easy-markdown-editor/issues/217
			}
			this.simplemde = undefined;
			this.textarea.nativeElement.value = '';
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}